// Original, server-only items. Difficulty is an authored blueprint, not a
// calibrated estimate. Four scenarios per conceptual family; numerical
// variants change actual inputs to a calculation rather than person names.
const choice = (topic, skills, options, cases) => ({
  topic, difficulty: 1, skills,
  variants: cases.map(([text, correct], index) => {
    const shift = index * 2 % 4;
    return { text, options: [...options.slice(shift), ...options.slice(0, shift)], correct: (correct - shift + 4) % 4, skills };
  }),
});
const format = value => Number.isInteger(value) ? String(value) : String(Number(value.toFixed(4))).replace('.', ',');
const answers = (value, unit, ...errors) => {
  const candidates = [value, ...errors, value + 1, value + 2, value + 3, value + 4];
  return [...new Set(candidates.filter(Number.isFinite).map(item => `${format(item)}${unit}`))].slice(0, 4);

};
const calc = (topic, skills, rows, question, solve) => ({
  topic, difficulty: 2, skills,
  variants: rows.map((row, index) => {
    const [answer, ...others] = solve(...row);
    const options = [...others]; options.splice(index, 0, answer);
    const text = question(...row) + (/\d,\d/.test(answer) ? ' При необходимости округлите результат до четырёх знаков после запятой.' : '');
    return { text, options, correct: index, skills };
  }),
});
const program = (...families) => ({ topics: [...new Set(families.map(item => item.topic))], families });

