export const dataProductLevelPrograms = Object.fromEntries(Object.entries(authored).map(([specialization, levels]) => [specialization,
  Object.fromEntries(Object.entries(levels).map(([grade, source]) => [grade, {
    topics: source.topics,
    families: source.families.map((item, familyIndex) => {
      const id = `dpl-${specialization.toLowerCase()}-${grade.toLowerCase()}-${familyIndex + 1}`;
      return { ...item, id, variants: item.variants.map((variant, index) => ({ ...variant, id: `${id}-${String.fromCharCode(97 + index)}` })) };
    }),
  }])),
]));

