export const dataProductLevelVacancies = Object.entries(vacancyDescriptions).flatMap(([specialization, levels]) =>
  Object.entries(levels).map(([grade, description]) => ({
    id: `dpl-${specialization.toLowerCase()}-${grade.toLowerCase()}-vacancy`,
    title: `${vacancyLabels[specialization]} ${grade === 'Intern' ? 'Стажёр' : grade}`,
    specialization, grade, description,
  })));
